//! Dataset definitions use native named setter descriptor semantics and real attribute storage.
use super::*;
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.begin_job();p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse_loaded_document("<!doctype html><html><body><p id=target></p><svg id=svg></svg></body></html>",&||Ok(())).unwrap();d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let location=crate::navigation::address("https://dataset-inspection.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&location);p.set_resource_base(&location);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}

#[test]
fn dataset_native_definitions_data_flags_do_not_replace_actual_native_attributes(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var n=document.getElementById('target'),d=n.dataset;for(var key of ['scalarName','raw\ud800Name']){var result=Object.defineProperty(d,key,{value:'native\udfff',writable:false,enumerable:false,configurable:false}),desc=Object.getOwnPropertyDescriptor(d,key);if(result!==d||d[key]!=='native\udfff'||!desc.writable||!desc.enumerable||!desc.configurable||desc.value!=='native\udfff')throw 'native named data definition';d[key]='changed';if(d[key]!=='changed'||!delete d[key]||Object.hasOwn(d,key))throw 'real native descriptor remains mutable';}"#);}

#[test]
fn dataset_native_definitions_writable_only_is_data_generic_descriptor_is_rejected(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var n=document.getElementById('target'),d=n.dataset,watch=new MutationObserver(function(){});watch.observe(n,{attributes:true});for(var key of ['scalarName','raw\ud800Name']){Object.defineProperty(d,key,{writable:false});if(d[key]!=='undefined')throw 'missing data value binds undefined';delete d[key];watch.takeRecords();for(var desc of [{},{enumerable:true},{configurable:false}]){var error;try{Object.defineProperty(d,key,desc);}catch(e){error=e;}if(!(error instanceof TypeError)||Object.hasOwn(d,key)||watch.takeRecords().length)throw 'generic descriptor is not data';}}"#);}

#[test]
fn dataset_native_definitions_accessors_and_mixed_descriptors_fail_without_native_mutation(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var n=document.getElementById('target'),d=n.dataset,hits=0,watch=new MutationObserver(function(){});watch.observe(n,{attributes:true});for(var key of ['scalarName','raw\ud800Name'])for(var desc of [{get:function(){hits++;return 'bad';}},{set:undefined},{value:'bad',get:undefined},{get:3}]){var error;try{Object.defineProperty(d,key,desc);}catch(e){error=e;}if(!(error instanceof TypeError)||hits||Object.hasOwn(d,key)||watch.takeRecords().length)throw 'descriptor refusal is real';}"#);}

#[test]
fn dataset_native_definitions_key_descriptor_fields_and_value_bind_in_order_once(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var n=document.getElementById('target'),d=n.dataset,order='',key={toString:function(){order+='k';return 'x\ud800Name';}},value={toString:function(){order+='x';return 'raw\udfff';}},desc={};for(var pair of [['enumerable','e',false],['configurable','c',false],['value','v',value],['writable','w',false]])(function(pair){Object.defineProperty(desc,pair[0],{get:function(){order+=pair[1];return pair[2];}});})(pair);Object.defineProperty(d,key,desc);if(order!=='kecvwx'||d['x\ud800Name']!=='raw\udfff')throw 'ordered native definition binding';var inherited=Object.create({value:'inherited',writable:false});Object.defineProperty(d,'y\ud800',inherited);if(d['y\ud800']!=='inherited')throw 'inherited descriptor field';"#);}

#[test]
fn dataset_native_definitions_abrupt_value_identity_and_invalid_name_order(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var n=document.getElementById('target'),d=n.dataset,marker={},error;try{Object.defineProperty(d,'bad\ud800-x',{value:{toString:function(){n.setAttribute('data-author','effect');throw marker;}}});}catch(e){error=e;}if(error!==marker||d.author!=='effect')throw 'same abrupt identity and author effect';var calls=0,error;try{Object.defineProperty(d,'bad\ud800-x',{value:{toString:function(){calls++;return 'value';}}});}catch(e){error=e;}if(calls!==1||!(error instanceof DOMException)||error.name!=='SyntaxError')throw 'native value precedes name validation';var error;try{Object.defineProperty(d,'x\ud800',{value:Symbol('value')});}catch(e){error=e;}if(!(error instanceof TypeError)||Object.hasOwn(d,'x\ud800'))throw 'native DOMString Symbol binding';"#);}

#[test]
fn dataset_native_definitions_observe_raw_names_previous_values_and_same_attr(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var n=document.getElementById('target'),d=n.dataset,watch=new MutationObserver(function(){});watch.observe(n,{attributes:true,attributeOldValue:true});Object.defineProperty(d,'x\ud800Name',{value:'first\udfff',configurable:false});var a=n.getAttributeNodeNS(null,'data-x\ud800-name');Object.defineProperty(d,'x\ud800Name',{value:'last\ud800',enumerable:false});var r=watch.takeRecords();if(a!==n.getAttributeNodeNS(null,'data-x\ud800-name')||a.value!=='last\ud800'||r.length!==2||r[0].target!==n||r[1].target!==n||r[0].attributeName!=='data-x\ud800-name'||r[1].attributeName!=='data-x\ud800-name'||r[0].oldValue!==null||r[1].oldValue!=='first\udfff')throw 'actual native definition records';if(!delete d['x\ud800Name']||a.ownerElement!==null)throw 'actual Attr detach';"#);}

#[test]
fn dataset_native_definitions_ignore_prototype_setters_and_author_attribute_shadows(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var n=document.getElementById('target'),d=n.dataset,hits=0;Object.defineProperty(DOMStringMap.prototype,'x\ud800',{set:function(){hits++;throw 'author setter';},get:function(){return 'author';},configurable:true});n.setAttribute=function(){throw 'author method';};Object.defineProperty(d,'x\ud800',{value:'native',writable:false});if(hits||d['x\ud800']!=='native'||n.getAttributeNS(null,'data-x\ud800')!=='native')throw 'real native named setter';delete d['x\ud800'];if(d['x\ud800']!=='author')throw 'author prototype retained';"#);}

#[test]
fn dataset_native_definitions_copy_storage_refusal_keeps_actual_dom_and_recovers(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var n=document.getElementById('target'),data=n.dataset;n.setAttributeNS(null,'data-x\ud800','old\udfff');var watch=new MutationObserver(function(){});watch.observe(n,{attributes:true,attributeOldValue:true});"#);let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;let limit=p.state.retained_limit;for copy in [true,false]{p.begin_job();if copy{p.state.copy_work=0;}else{p.state.retained_limit=p.state.retained;}let error=p.runtime.execute(&format!(r#"Object.defineProperty(data,'x\ud800',{{value:'{}'}});"#,"refused".repeat(200)),&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains(if copy{"string work"}else{"retained"}),"{error}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);p.state.retained_limit=limit;run(&mut d,&mut f,&mut p,r#"if(watch.takeRecords().length||data['x\ud800']!=='old\udfff')throw 'atomic definition refusal';"#);}run(&mut d,&mut f,&mut p,r#"Object.defineProperty(data,'x\ud800',{value:'recovered',configurable:false});var r=watch.takeRecords();if(r.length!==1||r[0].oldValue!=='old\udfff'||data['x\ud800']!=='recovered')throw 'native definition recovery';"#);}
